/**
 * @file    hal_timebase.c
 * @brief   HAL 1 ms time base on TIM6 instead of SysTick (DGEN-006).
 * @details Implements the project overrides of the weak STM32Cube HAL time
 *          base functions so that the HAL tick is generated by TIM6, a basic
 *          APB1 timer, while SysTick remains dedicated to the FreeRTOS kernel
 *          (`DRT-001`).  @c HAL_Init() calls @ref HAL_InitTick with
 *          TICK_INT_PRIORITY from board/stm32f7xx_hal_conf.h, and
 *          @c HAL_RCC_ClockConfig() calls it again after a clock-tree change,
 *          so the prescaler is recomputed from the final PCLK1 frequency.
 *
 *          TIM6 is clocked from PCLK1.  Per RM0410 the timer kernel clock is
 *          PCLK1 when the APB1 prescaler is 1 and twice PCLK1 otherwise.  The
 *          current 54 MHz PCLK1 with an APB1 divide-by-4 prescaler therefore
 *          gives a 108 MHz timer clock.  The prescaler register is programmed
 *          for a 1 MHz count and ARR for 1000 counts, hence one update event
 *          per millisecond.  The update interrupt adds uwTickFreq (1) to the
 *          HAL global uwTick, so the unchanged @c HAL_GetTick() and
 *          @c HAL_Delay() work in milliseconds.
 *
 *          The tick interrupt runs at TICK_INT_PRIORITY (15), the least
 *          urgent NVIC level.  That number is greater than
 *          configMAX_SYSCALL_INTERRUPT_PRIORITY (5), so FreeRTOS critical
 *          sections mask the tick; the handler deliberately calls no FreeRTOS
 *          API.  The handler only touches TIM6->SR, uwTick and uwTickFreq.
 * @author  Sandesh Ghimire <sandesh@soccentric.com>
 * @date    2026-11-03
 * @target  STM32F767ZIT6
 * @srs     DGEN-006 - the HAL time base uses a hardware timer other than
 *          SysTick (SysTick belongs to FreeRTOS, DRT-001).  Same scheme as
 *          the validation firmware (HWVAL GEN-012).
 * @ingroup clock
 */

#include "stm32f7xx_hal.h"

/** @brief TIM6 update interrupt handler; see the definition below. */
void TIM6_DAC_IRQHandler(void);

/**
 * @brief   Configure TIM6 as the 1 ms HAL time base.
 * @details Replaces the weak SysTick-based HAL_InitTick() so SysTick stays
 *          with FreeRTOS.  The timer kernel clock is derived from
 *          @c HAL_RCC_GetPCLK1Freq(): APB1 timers run at PCLK1 when the APB1
 *          prescaler is /1 and at twice PCLK1 otherwise (RM0410).  That clock
 *          is divided to 1 MHz by TIM6->PSC, and TIM6->ARR is set to 999 so
 *          that 1000 counts produce one update per millisecond.  Writing
 *          TIM6->EGR = TIM_EGR_UG latches PSC and ARR and reloads the
 *          counter; SR is then cleared so the software update leaves no
 *          pending flag.  UIE enables the update interrupt and CEN|URS starts
 *          the counter.  URS makes only a counter overflow generate the
 *          update interrupt, so the UG event above does not cause a spurious
 *          tick.  Finally the handler priority is stored in uwTickPrio and
 *          programmed into the NVIC with NVIC_SetPriority() and
 *          NVIC_EnableIRQ().
 *
 *          @c HAL_Init() calls this early, while the reset HSI still clocks
 *          APB1.  @c HAL_RCC_ClockConfig() calls it again at the end of
 *          @ref app_clock_init, so the prescaler is recalculated for the
 *          final 54 MHz PCLK1 (108 MHz timer clock) before the application
 *          relies on @c HAL_GetTick() or @c HAL_Delay().
 *
 * @param[in] TickPriority NVIC priority for TIM6_DAC_IRQn.  With the four
 *            implemented priority bits this is a number from 0 (most urgent)
 *            to 15 (least urgent); the project passes TICK_INT_PRIORITY = 15.
 *            The value is also stored in uwTickPrio.
 *
 * @return HAL_OK always.
 *
 * @pre  The RCC is programmed well enough for @c HAL_RCC_GetPCLK1Freq() to
 *       return the APB1 frequency in Hz.  @c HAL_Init() guarantees this at
 *       reset; @c HAL_RCC_ClockConfig() guarantees it for later calls.
 * @pre  TIM6 is not used by an application driver.  The basic timer has no
 *       other purpose in this firmware.
 * @post TIM6 counts at 1 MHz, TIM6->ARR is 999, the update interrupt is
 *       enabled in TIM6->DIER and in the NVIC, and uwTickPrio holds
 *       @p TickPriority.
 *
 * @note TIM6 and the DAC share TIM6_DAC_IRQn and TIM6_DAC_IRQHandler(); the
 *       DAC is not enabled by this build, so the vector belongs to the tick.
 * @note This function is not thread-safe: it reconfigures a running timer and
 *       the NVIC without masking interrupts.  Call it during start-up or
 *       while the scheduler is not using HAL timing.
 *
 * @warning The reload is fixed at 1 kHz and does not follow uwTickFreq.
 *          @c HAL_SetTickFreq() would re-enter this function but still leave
 *          the 1 ms period, while the ISR would add the new uwTickFreq to
 *          uwTick, scaling the tick incorrectly.
 * @warning The tick is the least urgent interrupt, so @c HAL_Delay() must
 *          never be called from an ISR: TIM6 cannot preempt the caller, no
 *          tick arrives, and the wait loop never completes.
 * @warning Unlike the weak HAL implementation, this override does not reject
 *          TickPriority >= (1UL << __NVIC_PRIO_BITS); an out-of-range value is
 *          truncated by NVIC_SetPriority().  The only caller passes 15.
 *
 * @see HAL_GetTick
 * @see HAL_Delay
 * @see HAL_SuspendTick
 * @see HAL_ResumeTick
 * @see TIM6_DAC_IRQHandler
 * @see app_clock_init
 */
HAL_StatusTypeDef HAL_InitTick(uint32_t TickPriority)
{
    uint32_t pclk1 = HAL_RCC_GetPCLK1Freq();
    /* APB timers run at PCLK x2 unless the APB prescaler is 1 (RM0410). */
    uint32_t timclk = ((RCC->CFGR & RCC_CFGR_PPRE1) == 0U) ? pclk1 : pclk1 * 2U;
    uint32_t prescaler = (timclk / 1000000U) - 1U;

    __HAL_RCC_TIM6_CLK_ENABLE();

    TIM6->CR1 = 0U;
    TIM6->PSC = prescaler;       /* 1 MHz count                          */
    TIM6->ARR = 1000U - 1U;      /* 1000 counts = 1 ms (uwTickFreq 1kHz) */
    TIM6->EGR = TIM_EGR_UG;      /* latch PSC/ARR, reset counter         */
    TIM6->SR  = 0U;
    TIM6->DIER = TIM_DIER_UIE;
    TIM6->CR1 = TIM_CR1_CEN | TIM_CR1_URS;

    uwTickPrio = TickPriority;
    NVIC_SetPriority(TIM6_DAC_IRQn, TickPriority);
    NVIC_EnableIRQ(TIM6_DAC_IRQn);

    return HAL_OK;
}

/**
 * @brief   Suspend the HAL tick by masking the TIM6 update interrupt.
 * @details Clears TIM_DIER_UIE and nothing else.  TIM6 keeps counting and its
 *          prescaler and ARR are untouched, so a later resume continues on the
 *          same timer phase; the HAL tick simply stops advancing.  This is the
 *          project replacement for the weak HAL routine that disables the
 *          SysTick interrupt.
 *
 *
 * @post TIM6 no longer requests update interrupts and uwTick stops
 *       incrementing.  The counter and the rest of TIM6->DIER are unchanged.
 *
 * @note An update request already pending in the NVIC when this function runs
 *       can still be serviced once; the handler clears UIF and adds one last
 *       tick.  No project source calls this function at present; it is part of
 *       the HAL low-power API and is documented for completeness.
 * @warning Time spent suspended is not recovered by @ref HAL_ResumeTick, so
 *          uwTick and every @c HAL_Delay() deadline drift behind wall-clock
 *          time by the length of the suspended interval.
 * @see HAL_ResumeTick
 * @see HAL_InitTick
 */
void HAL_SuspendTick(void)
{
    TIM6->DIER &= ~TIM_DIER_UIE;
}

/**
 * @brief   Resume the HAL tick after @ref HAL_SuspendTick.
 * @details Clears TIM6->SR first, which drops any update flag that accumulated
 *          while the interrupt was masked, then sets TIM_DIER_UIE to let the
 *          next counter overflow interrupt the core.  The counter itself was
 *          never stopped, so the first tick after resume arrives at the next
 *          1 ms boundary rather than 1 ms after the call.
 *
 *
 * @pre  TIM6 has been configured by @ref HAL_InitTick at least once.
 * @post Update interrupts are enabled again and no stale UIF is left to
 *       produce an immediate extra tick.
 *
 * @note The time between suspend and resume is not added to uwTick; the HAL
 *       tick is monotonic but is not a wall-clock reference across a suspend.
 * @note No project source calls this function at present; it pairs with
 *       @ref HAL_SuspendTick for HAL low-power use.
 * @see HAL_SuspendTick
 * @see HAL_InitTick
 */
void HAL_ResumeTick(void)
{
    TIM6->SR = 0U;
    TIM6->DIER |= TIM_DIER_UIE;
}

/**
 * @brief   Advance the HAL tick on a TIM6 update event.
 * @details Reads TIM6->SR and, when UIF is set, clears it by writing
 *          ~TIM_SR_UIF and adds uwTickFreq to the global uwTick.  With the
 *          default uwTickFreq (HAL_TICK_FREQ_DEFAULT, 1 kHz) each call advances
 *          @c HAL_GetTick() by 1 ms.  The handler performs the same increment
 *          as @c HAL_IncTick() would, but does not call that weak function and
 *          calls no FreeRTOS API.
 *
 *
 * @pre  @ref HAL_InitTick has configured TIM6 and enabled TIM6_DAC_IRQn.
 * @post UIF is cleared, uwTick has advanced by uwTickFreq, and the handler is
 *       ready for the next update event.
 *
 * @note Execution context: interrupt.  Invoked by the TIM6_DAC vector at
 *       uwTickPrio (15, the least urgent level).  It must stay short and must
 *       not block; it deliberately calls no FreeRTOS API, although priority 15
 *       would permit a FromISR call.  A task may read @c HAL_GetTick()
 *       concurrently because the 32-bit read and write are atomic on
 *       Cortex-M7.
 * @note Because 15 is greater than configMAX_SYSCALL_INTERRUPT_PRIORITY (5),
 *       FreeRTOS critical sections mask this interrupt.  Ticks that fall
 *       inside a critical section are delayed, and if several update events
 *       coalesce into one UIF only one uwTickFreq increment is counted, so
 *       uptime can lag wall-clock time.
 * @warning TIM6_DAC_IRQn is shared with the DAC.  Enabling the DAC interrupt
 *          later requires extending this handler; it currently assumes every
 *          interrupt on the vector is a TIM6 update.
 * @see HAL_InitTick
 * @see HAL_GetTick
 */
void TIM6_DAC_IRQHandler(void)
{
    if ((TIM6->SR & TIM_SR_UIF) != 0U) {
        TIM6->SR = ~TIM_SR_UIF;
        uwTick += uwTickFreq;
    }
}
